        if test_input[rr][c] != bg:
            return test_input[rr][c]
    return None

output = [[bg]*16 for _ in range(6)]
for r in range(6):
    for c in range(16):
        if test_input[r][c] != bg:
            output[r][c] = test_input[r][c]
        else:
            # Check what would be returned by both scans
            # If only ONE returns something, use it
            v_horiz = first_val_at_anchor_col(r)
            v_vert = first_val_at_anchor_row(c)

            print(f"Cell ({r},{c}): horiz={v_horiz}, vert={v_vert}")

            if v_horiz is not None and v_vert is not None:
                conn = conn_same if v_horiz == v_vert else conn_diff
                output[r][c] = conn
            elif v_horiz is not None:
                output[r][c] = v_horiz  # Just copy the color? Or maybe connect?
            elif v_vert is not None:
                output[r][c] = v_vert

print("\n\nFull output:")
for row in output:
    print(row)

